/// The prefs filename under the tui config dir.
const PREFS_FILE: &str = "prefs.json";

/// The external-media handoff preference (`tui.md` § External media handoff).
///
/// Serialized as its lowercase token (`ask`/`always`/`never`) — the same token
/// the `tui-settings-external-media` select round-trips through `/element/select`.
#[derive(Debug, Clone, PartialEq, Eq, Default, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ExternalMediaMode {
    /// Prompt inline before launching anything (the doc default).
    #[default]
    Ask,
    /// Always hand off to the OS default handler.
    Always,
    /// Never launch anything; show metadata only.
    Never,
    /// A mode a newer tui wrote into `prefs.json` that this build cannot name —
    /// the open arm of `transport.md` § Rule 3 in full (*Open, carrying*). The
    /// file is rewritten whole on every change, so the arm holds the exact
    /// token read and re-emits it. It **behaves as [`Self::Never`]** — launch
    /// nothing ([`external_media_outcome`]) — and the select paints that
    /// behaviour; it is never one of the select's options.
    #[serde(untagged)]
    Other(String),
}

impl ExternalMediaMode {
    /// The three modes in the select's option order (ask → always → never).
    pub const ALL: [ExternalMediaMode; 3] = [Self::Ask, Self::Always, Self::Never];

    /// The stable wire/UI token — what `get_text` returns and `select` takes.
    /// A carried [`Self::Other`] answers its own token.
    pub fn token(&self) -> &str {
        match self {
            Self::Ask => "ask",
            Self::Always => "always",
            Self::Never => "never",
            Self::Other(token) => token,
        }
    }

    /// Parse a token back to a mode; `None` for anything else (the select never
    /// sends anything but the three, but a hand-edited prefs file might).
    pub fn from_token(token: &str) -> Option<Self> {
        match token {
            "ask" => Some(Self::Ask),
            "always" => Some(Self::Always),
            "never" => Some(Self::Never),
            _ => None,
        }
    }

    /// The localized label the human reads (the select paints this; `get_text`
    /// still returns [`Self::token`] — the `vps-location-picker` split).
    /// A carried [`Self::Other`] paints what this build does with it: never.
    pub fn label(&self) -> &'static str {
        match self {
            Self::Ask => tui_settings_strings::EXTERNAL_MEDIA_ASK,
            Self::Always => tui_settings_strings::EXTERNAL_MEDIA_ALWAYS,
            Self::Never | Self::Other(_) => tui_settings_strings::EXTERNAL_MEDIA_NEVER,
        }
    }
}

/// The client-local tui preferences persisted in `prefs.json`. Additive both
/// ways — a new field defaults, so an older file loads unchanged, and a newer
/// file's keys this build does not know are kept in [`Self::extra`] and
/// written back, so a save here never drops a newer tui's preference.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct TuiPrefs {
    #[serde(default)]
    pub external_media: ExternalMediaMode,
    /// Every key a newer tui wrote that this build does not name, re-emitted
    /// as read (the `extra` catch-all of `version-compatibility.md`
    /// § Dimension 1).
    #[serde(flatten)]
    pub extra: serde_json::Map<String, serde_json::Value>,
}

impl TuiPrefs {
    /// Read `prefs.json`: the defaults when there is no file (a fresh install),
    /// `Err` when there is one this build cannot read — corrupt, or a newer
    /// tui's reshaped file. The two are different states: the caller runs on
    /// defaults either way, but never saves over the second
    /// ([`SettingsState::save`]; `transport.md` § Rule 3 in full → *The store
    /// around the enum*), so what a newer build chose survives a downgrade.
    fn load(path: &Path) -> Result<TuiPrefs, String> {
        let bytes = match std::fs::read(path) {
            Ok(bytes) => bytes,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(TuiPrefs::default()),
            Err(e) => return Err(format!("reading {}: {e}", path.display())),
        };
        serde_json::from_slice(&bytes).map_err(|e| format!("parsing {}: {e}", path.display()))
    }

    /// Write `prefs.json` via tmp+rename, so a crash can never truncate it. A
    /// failure is silent (the next launch just reads the prior file).
    fn save(&self, path: &Path) {
        let Ok(bytes) = serde_json::to_vec_pretty(self) else {
            return;
        };
        if let Some(parent) = path.parent() {
            let _ = std::fs::create_dir_all(parent);
        }
        let tmp = path.with_extension("json.tmp");
        if std::fs::write(&tmp, &bytes).is_ok() {
            let _ = std::fs::rename(&tmp, path);
        }
    }
}

/// Park `state` on Settings → Folders with ONE expanded website-enabled folder and no own
/// tiers — the state in which `folder-paywall-tier-select` paints DISABLED
/// ("create a tier first": there is nothing to paywall to).
///
/// A `#[cfg(test)]` seam rather than widened field visibility, the
/// `set_step_for_test` idiom: `SettingsState`'s sub-state stays private to this
/// module, and `crate::automation`'s actuation-gate pins — which must drive a
/// really-disabled picker, not a synthetic one — get the one state they need
/// through a named door.
#[cfg(test)]
pub(crate) fn park_on_disabled_paywall_select_for_test(state: &mut SettingsState) {
    state.sub = SubPage::Folders;
    state.folders.expanded = Some(0);
    state.devices.snapshot = Some(fauna_devices_machine::DevicesSnapshot {
        folders: vec![fauna_devices_machine::FolderSummary {
            id: 1,
            name: "site".to_string(),
            website_enabled: true,
            ..Default::default()
        }],
        ..Default::default()
    });
    assert!(
        state.folders.own_tiers.is_empty(),
        "premise: no own tiers is what disables the paywall picker"
    );
}

/// Which settings surface is showing: the rail Root, or a sub-page.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum SubPage {
    /// The rail landing — the Status surface (`settings.md` § Live-data
    /// placement: account id + copy + quota) plus the rail rows drilling into
    /// the other sub-pages. This is where `navigate_to("settings")` lands (the
    /// desktop shell lands on Status, its first rail entry); the settings root
    /// IDs the driver reads without a sub-page nav (`account-actor-id`,
    /// `quota-*`) live here.
    #[default]
    Root,
    /// The Account sub-page (`settings.md` § Layout & flow — the pure-actions
    /// surface): handle change, identity export, sign out, delete account
    /// (nav id `account`).
    Account,
    /// The Privacy sub-page (`settings.md` § Layout & flow items 5–7): inbox
    /// mode, spam-classifier preferences, email filter rules (nav id
    /// `privacy`). Self-fetches on every visit (`route_subpage`'s
    /// `Op::FetchPrivacy`).
    Privacy,
    /// The "Mail & Calendar" sub-page (`ui/mail-settings.md`; nav id `mail-settings`).
    /// Self-hydrates on every visit (`route_subpage`'s `Op::HydrateMail`), the
    /// Privacy shape — the shared machine's snapshot is the whole render source.
    Mail,
    /// The `tui-settings` external-media page.
    TuiSettings,
    /// The Settings → Logs page (the client's durable log record —
    /// `observability.md` § Surfaces; ui.yaml `settings-logs`).
    Logs,
    /// The Settings → Devices sub-page (`ui/devices.md`; nav id `devices`) —
    /// the device roster only (2026-06-28 unification moved the folder
    /// wizard/list/conflicts to the separate `folders` sub-page). Self-hydrates
    /// on every visit (`route_subpage`'s `Op::HydrateDevices`), the Mail/Privacy
    /// shape.
    Devices,
    /// The Settings → Sessions sub-page (`ui/sessions.md`; nav id `sessions`)
    /// — the live sessions list, sign out everywhere else, the 24-hour lock.
    /// Self-hydrates on every visit (`route_subpage`'s `Op::Sessions`).
    Sessions,
    /// The Settings → Folders sub-page (`ui/folders.md`; nav id
    /// `folders`) — the control-plane core: list + in-place config + conflict
    /// review + create wizard, over the SAME shared `DevicesMachine` the roster
    /// above uses (`devices.folders`/`.conflicts`/`.wizard`). Self-hydrates on
    /// every visit like [`Self::Devices`].
    Folders,
    /// The Settings → AT Protocol sub-page (`ui/atproto.md`; nav id `atproto`) —
    /// the integration-depth selector (Off/Linked/Hosted-visible/Hosted-full),
    /// its transition card, the Linked-account panel (the shared
    /// `bridge-card` embedded via `crate::bridges::embed_bridge_card`), the
    /// hosted identity panel, and the F1 login-plane panel (app credentials +
    /// connected apps + the external-apps kill-switch, gated on level =
    /// hosted_full) — all over the shared `AtprotoSettingsMachine`.
    /// Self-hydrates on every visit (`route_subpage`'s `Op::HydrateAtproto`,
    /// which ALSO best-effort refreshes the app-wide bridges snapshot the
    /// Linked panel reads from), the Mail/Devices shape.
    Atproto,
    /// The Settings → Nests sub-page (`ui/nests.md`) — the nests the user's
    /// content lives on (home + pairings) plus the per-row nest-trust facet
    /// (Now/History lens, grants, backup trust rows, the mint flow). The nav id
    /// is **`nests`** fleet-wide (the one slug the shared
    /// `LinkedNestsActions.navigate()` sends every app).
    /// Self-hydrates on every visit (`route_subpage`'s `Op::HydrateNests`), the
    /// Mail/Devices shape.
    Nests,
    /// The Settings → Muted words sub-page (nav id `muted-words`) — the tier-1
    /// user keyword filter (`content-moderation-and-ranking.md` § Q3; the rail
    /// slot sits after Privacy per `settings.md` § Navigation model). Self-loads
    /// on every visit (`route_subpage`'s `Op::LoadMutedWords`), the Privacy
    /// shape — the list is also what the conversation-bubble collapse reads, so
    /// a visit refreshing it keeps both surfaces on one copy.
    MutedWords,
    /// The Settings → Task delegation sub-page (nav id `task-delegation`) — the
    /// cross-participant surface: one row per heavy task kind with its current
    /// runner and assignment picker (`participants.md` § Task delegation; the
    /// rail slot sits after Nests per `settings.md` § Navigation model).
    /// Self-loads on every visit (`route_subpage`'s `Op::LoadTaskDelegation`),
    /// the Privacy shape — the lease half is LIVE state, so a cached render
    /// would name a runner that has since handed over.
    TaskDelegation,
    /// The Settings → Connected apps sub-page (nav id `connected-apps`;
    /// `ui/connected-apps.md`) — the one roster of everything acting for the
    /// user from outside the seven apps, the typed-code *Connect an app* start
    /// and the quiet-push Requests tray. Rail slot after Task delegation.
    /// Self-refreshes on every visit (`route_subpage`'s `Op::ConnectedApps`
    /// `Refresh`): rows are nest state read on every open.
    ConnectedApps,
    /// The Settings → Mail → Aliases sub-page (`behavior/mail-aliases.md`
    /// § Aliases UX; nav id `mail-aliases`) — the user's own extra mail
    /// addresses: the canonical primary, exact aliases, wildcard prefixes and
    /// disposable mints, with per-alias label / spam-threshold / rate-cap /
    /// on-off controls plus bulk paste-import. Self-hydrates on every visit
    /// (`route_subpage`'s `Op::HydrateMailAliases`), the Mail/Nests shape — the
    /// shared machine's snapshot is the whole render source, so a visit without
    /// a fresh hydrate would paint a stale list (and, pre-first-hydrate, no rows
    /// at all).
    MailAliases,
    /// The Settings → Mail → Spam sub-page (`behavior/mail-spam.md` § Reset /
    /// § Undo + `behavior/report-sharing.md` § Client wire; nav id `mail-spam`)
    /// — the user's own per-account spam classifier: reset, the
    /// deployment-baseline opt-in, the training-history list with per-row undo,
    /// and the distributed-report-sharing opt-in + transparency list.
    /// Self-hydrates on every visit (`route_subpage`'s `Op::HydrateMailSpam`)
    /// and that is a REQUIREMENT, not the Mail/Nests habit: the history changes
    /// *outside* the app — a third-party MUA setting the IMAP `\Junk` flag
    /// trains the model and appends a row (`mail-spam.md` § Implementation
    /// status item 5, *Refresh-on-visible requirement (cross-app)*).
    MailSpam,
    /// The Settings → Mail → Export mailbox sub-page
    /// (`behavior/mail-export.md` § UX shape; nav id `mail-export`) — the
    /// five-step wizard (Format → Scope → Confirm → Progress → Done) that pulls
    /// the user's whole mailbox out in an MUA-portable format. Self-hydrates on
    /// every visit (`route_subpage`'s `Op::HydrateMailExport`), the Lists shape:
    /// the scope step's mailbox options AND any session to resume are both the
    /// machine's snapshot, so a visit without a fresh hydrate would offer a stale
    /// scope and miss a run started on another device.
    MailExport,
    /// The Settings → Mail → Import mailbox sub-page
    /// (`behavior/mailbox-migration.md` § UX shape; nav id `mail-import`) — the
    /// five-step wizard (Source → Scope → Confirm → Progress → Done) that pulls
    /// mail from a foreign IMAP server into the user's Fauna mailbox,
    /// client-driven, credentials never touching nest. Self-hydrates on every
    /// visit (`route_subpage`'s `Op::HydrateMailImport`), the Export shape: the
    /// scope step's mailbox options AND any session to resume are both the
    /// machine's snapshot.
    MailImport,
    /// The Settings → Import from other services sub-page
    /// (`behavior/archive-import.md` § The wizard and its machine; nav id
    /// `archive-import`) — the six-step wizard (Source → Archive → Scope →
    /// Confirm → Progress → Done) that reads a Facebook/Instagram export zip
    /// and re-authors it into the user's own posts, albums and events.
    /// Self-hydrates on every visit (`route_subpage`'s
    /// `Op::HydrateArchiveImport`): a folder found at hydrate lands the page on
    /// Progress/Paused (restart-resume).
    ArchiveImport,
    /// The Settings → Mail → Lists sub-page (`behavior/mail-mass-mailing.md`
    /// § `mail-lists` page UX; nav id `mail-lists`) — the user's own mailing
    /// lists (a list is a sixth alias kind): the rows with their member counts
    /// and quota meters, the add/edit sheet, and the cascading delete.
    /// Self-hydrates on every visit (`route_subpage`'s `Op::HydrateMailLists`),
    /// the Aliases shape — the shared machine's snapshot is the whole render
    /// source, including the domain options every create needs.
    MailLists,
    /// The Settings → Mail → List members sub-page
    /// (`behavior/mail-mass-mailing.md` § `mail-list-members` page; nav id
    /// `mail-list-members`) — one list's members: the summary, the rows with
    /// their subscribe status, the add + bulk-import sheets, and per-member
    /// unsubscribe / resubscribe.
    ///
    /// Unlike every sibling, its machine is **per-list**, so the nav edge
    /// selects a list (the one a `mail-lists` row asked for, else the first)
    /// and rebuilds the machine before hydrating — see
    /// [`mail_list_members::MailListMembersState::select`].
    MailListMembers,
    /// The Settings → Personalization home (`content-moderation-and-ranking.md`
    /// § Tier-3; nav id `personalization`) — the user's personalization hub. tui
    /// builds its SPINE + the SUBSCRIBED-labelers facet; the trained-topic-factor
    /// facet (`behavior/topic-factors.md`) and the engagement-cue controls
    /// (`behavior/engagement-cues.md`) are separate feature families, unbuilt here
    /// and tracked in `ui-actual-tui.yaml`'s `personalization` block. Self-refreshes
    /// on every visit (`route_subpage`'s `Op::RefreshLabelerCatalog`), the
    /// Mail/Nests shape — `subscribed` is per-actor state another device may have
    /// changed, so a cached render would show a subscription the user dropped.
    Personalization,
    /// The Settings → Community labelers catalog (`content-moderation-and-ranking.md`
    /// § Tier-3; nav id `labeler-catalog`) — browse every published tier-3 labeler,
    /// inspect its re-verified signed metadata before granting it your content, and
    /// (un)subscribe. Shares [`Self::Personalization`]'s machine and snapshot: the
    /// home is this page's `entries` filtered to `subscribed`, never a second fetch.
    /// Self-refreshes on every visit for the same reason — and additionally because
    /// the catalog is nest-GLOBAL, so a labeler published by anyone since the last
    /// visit would otherwise never appear.
    LabelerCatalog,
    /// The Settings → Web sub-page (`ui/settings.md` § Navigation model rail slot;
    /// feature owner `behavior/web-content-hosting.md`; nav id `web`) — the
    /// per-user subdomain opt-in that serves this actor's `web` content at
    /// `https://<handle>.<domain>/`, with the live URL (or the reason there
    /// isn't one) and the content explainer. Self-hydrates on every visit
    /// (`route_subpage`'s `Op::HydrateWeb`), the Mail/Nests shape — the opt-in is
    /// per-actor nest state another device may have flipped.
    Web,
    /// The Settings → Subscriptions sub-page (`ui/settings.md` § Navigation model
    /// rail slot; feature owner `behavior/monetization.md` § Pillar 1 UX surface
    /// 3; nav id **`subscription-settings`** — the slug the shared
    /// `SubscriptionsActions.navigate_settings()` sends every app, which here
    /// equals the ui.yaml page key) — the CONSUMER side: what this user
    /// subscribes to across all creators, with per-row unsubscribe, plus the
    /// Pillar-3 claim-code redemption. The author-side tier management is the
    /// separate profile Tiers tab (`crate::profile::tiers`). Self-hydrates on
    /// every visit (`route_subpage`'s `Op::SubscriptionsConsumer`), the
    /// Mail/Nests shape — a grant the author's client committed since the last
    /// visit is exactly what this page exists to show.
    Subscriptions,
    /// The Settings → General sub-page (`settings.md` § Navigation model rail
    /// slot; nav id `general`) — tui's scoped-down terminal-native equivalent
    /// of the other apps' appearance/startup/updates page: tui inherits the
    /// terminal's own color scheme (no picker to force) and has no OS-level
    /// autostart, tray, or in-app updater, so the surface is a short
    /// appearance note plus the app version. No RPC hydrate — purely static.
    General,
    /// The Settings → Encryption sub-page (`settings.md` § Navigation model
    /// rail slot; nav id `encryption`) — the MLS key-package pool: the
    /// available count, a low-key warning, and a manual refresh (mints +
    /// uploads fresh packages). Mirrors linux's `settings/encryption.rs`.
    /// Self-hydrates on every visit (`route_subpage`'s `Op::HydrateEncryption`,
    /// a pure RPC count read); the refresh action separately reaches the
    /// durable `ConversationsManager` (`Op::RefreshKeyPackages`) since minting
    /// must ride the session's MLS engine, not a one-off RPC client.
    Encryption,
    /// The Settings → Members To Review sub-page (`ui.yaml` page
    /// `member_review`; nav id `member-review`) — the **permanent** half of the
    /// post-succession unattested-member review (`succession-aftermath.md`
    /// § Propagation, ruling 1), holding whatever the ephemeral kit-side pass on
    /// [`Self::Account`] left unanswered. Self-reads the roster on every visit
    /// ([`member_review_hydrate_op`]), the Mail/Devices shape and for the same
    /// reason: a verdict another device already recorded is exactly what this
    /// page must not re-ask about. ⚠ Unlike the ephemeral pass it carries **no**
    /// ceremony gate — a deferred backlog has to outlive the app run that
    /// raised it, which is the hole the permanent view was ratified to close.
    MemberReview,
}

/// The quota-section display, formatted once from a [`QuotaGetReply`]
/// (`settings.md` § Quota). `None` until the `fauna.quota.get` fetch resolves —
/// the `quota-section` element does not register while `None`, so the driver's
/// `wait_for("quota-section")` waits for real data (linux's `{#if quota}` /
/// `set_visible(true)`-on-resolve shape). Strings, not numbers: the shared
/// `fauna_core::format::byte_size` already localized them, so the render is dumb.
#[derive(Debug, Clone, PartialEq)]
pub struct QuotaView {
    /// `"used / max"` (e.g. `"0 B / 1 GB"`) — inbox bytes.
    pub inbox: String,
    /// `"used / max"` — storage bytes.
    pub storage: String,
    /// `"used / max"` — device count (bare integers, no byte units).
    pub devices: String,
    /// Storage `used / max` as a zero-guarded, clamped 0.0-1.0 ratio (the
    /// shared `fauna_core::format::quota_fraction`) — backs `settings-storage-bar`,
    /// the visual-bar sibling of `storage` above (`quota-display` component,
    /// `ui.yaml`). `f64`, so `QuotaView` can no longer derive `Eq`.
    pub storage_fraction: f64,
}

/// The Settings page's state: which sub-page shows + the client-local prefs +
/// the authenticated account surface (`settings.md` § State & data shape).
/// The change-passphrase modal's three raw buffers (`settings.md`
/// § Credential store; mechanics `architecture/apps/tui.md` § Credential
/// storage). Held as `Some` while the modal is armed —
/// `credential-store-rekey-modal` paints iff so, the media confirm-modal
/// idiom. [`SecretString`]s so disarming (cancel, success, the Account nav
/// edge) zeroizes the passphrases rather than merely dropping them; the
/// painted/registered text is a same-length bullet mask (the tui-unlock
/// contract), so the raw values never enter the automation registry or
/// `/app/state`.
#[derive(Default)]
pub struct RekeyModalState {
    pub current: SecretString,
    pub new_pass: SecretString,
    pub confirm: SecretString,
}

/// One scheduled, still-cancellable delayed action — the account page's
/// `pending-action-item` row source (`settings.md` § Pending actions). A
/// projection of the wire `PendingActionSummary`, filtered to
/// `status == "pending"` at fold time (an executed/cancelled/expired action
/// has no cancel window left, so the section has nothing to offer on it).
/// ⚠ Deliberately does NOT carry the verb's new value into any cache — the
/// change has not applied (the section's own iron-clad); `target` exists
/// only to be *described*, never stored as state.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct PendingActionRow {
    /// The wire row id — `fauna.pending_actions.cancel`'s argument.
    pub id: i64,
    /// The wire discriminator (`handle.change` / `account.delete` /
    /// `snapshot.delete`, open set) — resolved to a human sentence by
    /// `account::pending_description`.
    pub action_type: String,
    /// The verb's target (the new handle, the snapshot id); `None` for
    /// self-scoped actions.
    pub target: Option<String>,
    /// Unix seconds the nest will execute at — painted absolute via the
    /// shared `fauna_core::format::format_unix_local`.
    pub execute_after: i64,
}

pub struct SettingsState {
    pub sub: SubPage,
    pub prefs: TuiPrefs,
    /// The Settings → Logs severity-filter index (`0` = All; `1..=5` map to a
    /// [`fauna_log::LogLevel`] threshold via `fauna_log::format::level_for_index`).
    /// Session-local UI state, reset to All on every nav to the Logs page (see
    /// [`route_subpage`]) — not persisted, so it carries no wire / at-rest shape.
    pub log_filter: u32,
    /// The `prefs.json` path, resolved once at App construction. `None` in unit
    /// tests (`SettingsState::default`) so a test never touches the developer's
    /// real `$XDG_CONFIG_HOME/fauna-tui/prefs.json` — writes are skipped, reads
    /// default. The real App resolves it from [`crate::session::config_dir`].
    prefs_path: Option<PathBuf>,
    /// `prefs.json` exists but this build could not read it at load: the page
    /// runs on defaults and [`Self::save`] never writes over the file.
    prefs_unreadable: bool,

    // ── authenticated account surface (populated by `attach_session` at the
    //    post-auth hook; empty/None pre-login, so the Root renders no account IDs) ──
    /// The live nest client — the quota + handle-change RPC seam. `None`
    /// pre-login (the account IDs don't render, so nothing calls it).
    nest: Option<Arc<NestClient>>,
    /// The account-store runtime's handle — the W3 (account-data-plane.md § Workstreams) read-path-inversion seam
    /// (`account-data-plane.md` § The account store → *The client-side
    /// lifecycle*). Arrives asynchronously after the post-auth hook (the
    /// assembly opens a store + mints/loads the writer key, so `establish`
    /// spawns it — `DataMessage::AccountStoreReady` lands it here); `None`
    /// pre-login, before the assembly settles, or when it failed. A
    /// preference page reads the live slot instead ([`Self::preference_store`]),
    /// so a gesture made before the assembly settles waits for it.
    pub(crate) account_store: Option<fauna_sync_engine::account_runtime::AccountStoreHandle>,
    /// The same handle, readable from a task that outlives the borrow of
    /// `App` — the source a shared seam reads fresh on every use (the DNS
    /// record's store, `fauna_client_dns::AccountHandleSource`). Kept in step
    /// with [`Self::account_store`]: filled by the session's assembly task the
    /// moment it settles (and again at `AccountStoreReady`), replaced by a
    /// fresh slot at the sign-out teardown ([`Self::set_account_store`]).
    pub(crate) account_runtime: AccountRuntimeSlot,
    /// The **in-flight** assembly's handle-to-be — the same handle
    /// [`Self::account_store`] will hold, delivered on a channel the teardown
    /// can await *without* draining the UI queue `AccountStoreReady` rides.
    ///
    /// ⚠ **This exists because a sign-out can land mid-assembly, and until
    /// 2026-09-03 nothing could see the store then.** `establish` spawns the
    /// assembly detached, and `AccountStoreRuntime::start` opens the store on
    /// its own OS thread *before* returning — so from the moment the writer key
    /// is minted until `AccountStoreReady` is processed, `account_store` is
    /// `None` while a real connection holds `account-store.db` open. A sign-out
    /// in that window took `None`, stopped nothing, and erased anyway: on
    /// Windows the sweep then failed with `os error 32` and left the signed-out
    /// user's whole account store on disk (measured `--app tui` on Windows,
    /// 2026-09-03 — the erase's own `SURVIVED` warning beside an absent
    /// store-stopped line is the signature). `shutdown()` is the ONLY thing
    /// that closes that store thread, and it needs the handle, so the teardown
    /// has to be able to *wait* for one.
    ///
    /// A failed assembly resolves it immediately with nothing to stop, so it
    /// never spends the teardown budget.
    ///
    /// ⚠ **The seam is SHARED; the slot is tui's own, and that split is the
    /// design rather than a compromise** (converged 2026-09-06). The wait —
    /// `fauna_client_account_runtime::{assembly_channel, PendingAssembly,
    /// stop_account_runtime}` — is one implementation for every host: linux and
    /// the `fauna-ffi` seat reach it through `AccountRuntimeHost`, tui holds it
    /// here. What tui deliberately does **not** adopt is that host's *slot*:
    /// `account-data-plane.md` § The account store → *The client-side
    /// lifecycle* rules tui a NON-consumer of the lifecycle ("do not 'finish'
    /// the lift by moving it over"), because its supersession guard is an
    /// actor-id match against the live session in `app.rs` — exact where it
    /// runs — and moving this handle into the host would put it in a process
    /// static, against this app's no-globals, `App`-owned-state shape. Same
    /// contract, two correct mechanisms; the WAIT is what all of them genuinely
    /// share.
    pub(crate) account_store_assembly: Option<fauna_client_account_runtime::PendingAssembly>,
    /// The co-present offline-share ceremony's page state (`p2p.md` § Offline
    /// share initiation). Lives beside [`Self::account_store`] because the
    /// initiator's deliver step reads its authority seam through that handle;
    /// the seat inside binds lazily, when a panel opens.
    #[cfg(feature = "p2p-share")]
    pub(crate) offline_share: crate::offline_share::OfflineShareState,
    /// The share plane's paint cell (`share-serve-status` + the
    /// `share-transfer-*` rows). Installed when the glue task starts at the
    /// `AccountStoreReady` edge; `None` before then and when the plane never
    /// started this session — the surface simply does not render (a
    /// never-started plane has nothing honest to say).
    #[cfg(feature = "p2p-share")]
    pub(crate) share_plane: Option<crate::share_glue::SharePlaneCell>,
    /// The identity's actor-id hex — `account-actor-id` and what
    /// `account-actor-id-copy-btn` copies (from the session, no fetch).
    account_actor_id: String,
    /// The user's current handle — rides in the identity-export QR payload so a
    /// scanned import pre-fills the handle step (`settings.md` § Identity export).
    handle: String,
    /// The nest's url, captured at [`Self::attach_session`]. The Web sub-page
    /// derives the hosting **domain** from it (`fauna_core::format::url_host`),
    /// which with `handle` is what `subdomain_view` needs to build the
    /// `https://<handle>.<domain>/` address.
    node_url: String,
    /// The Ed25519 identity secret (hex) — read only when the identity-export QR
    /// is revealed, to build its payload. Held in memory like every other tui
    /// page's secret (`profile`/`events`), and **never** serialized into
    /// `state_json` (the secret must not ride a settings snapshot). A
    /// `SecretString` (not a plain `String`) so `clear_session` actually
    /// zeroizes it on drop, not just clears its length.
    secret_hex: SecretString,
    /// The fetched quota, or `None` until `fauna.quota.get` resolves (see
    /// [`QuotaView`] — the section is hidden until then).
    quota: Option<QuotaView>,
    /// The feature plane's transparency rows, or `None` until
    /// `fauna.features.status` resolves — `feature-limits-section` does not
    /// register while `None`, the `quota` shape exactly (a section painted
    /// before its data would state a settled claim it has no basis for, the
    /// un-hydrated-paint defect this queue has now hit six times).
    ///
    /// Derived entirely by `fauna_client_features` — this page holds the rows
    /// and renders them, and re-deriving any of it here is the documented way
    /// to get the plane wrong (`dynamic-features.md` § Implementation status
    /// item (c)).
    features: Option<Vec<fauna_client_features::FeatureRow>>,
    /// The shared Status snapshot's node leg (`ui/status.md` § State & data
    /// shape), or `None` until `fauna.nest.info` resolves on the landing op —
    /// the `quota`/`features` hydrate-gates-paint shape: the Node section does
    /// not register while `None`.
    status_node: Option<fauna_client_status::NodeLeg>,
    /// The snapshot's MLS leg input from the nest — the bearer's own published
    /// key-package count, or `None` until `fauna.conversations.keypackage.count`
    /// resolves on the landing op (the channel count is local and needs no
    /// fetch; the section gates on this half).
    status_key_packages: Option<u64>,
    /// The self-limits control inside `feature-limits-section`
    /// (`dynamic-features.md` § Authoring surfaces): the bearer's own AUTHORED
    /// documents and the shared editor while one is open.
    own_limits: OwnLimitsState,
    /// The Encryption sub-page's available MLS key-package count, or `None`
    /// until `fauna.conversations.keypackage.count` resolves — the
    /// `quota`/`features` hydrate-gates-paint shape: an un-hydrated page
    /// states no count rather than a stale or zero one.
    encryption_key_packages: Option<u64>,
    /// The Encryption sub-page's error line (a failed count read or a failed
    /// refresh) — `web`'s `error` field shape, reset on the next successful
    /// read.
    encryption_error: Option<String>,
    /// The Recovery kit section's view state (`settings.md` § Recovery kit).
    /// Hydrated at the Account nav edge, like the other sub-page states.
    recovery: recovery::RecoveryState,
    /// The standing pending-actions section's rows (`settings.md` § Pending
    /// actions): the calling actor's still-`pending` delayed verbs (handle
    /// change / account delete / snapshot delete), refreshed at the Account
    /// nav edge and after every verb that schedules or cancels one. `None` =
    /// not yet hydrated this visit, so the section makes no settled
    /// "nothing scheduled" claim it has no basis for (the un-hydrated-paint
    /// rule); `Some(empty)` is the honest empty.
    pub(crate) pending_actions: Option<Vec<PendingActionRow>>,
    /// The `new-handle` input buffer (`settings.md` § Handle change). A local
    /// buffer committed only on `change-handle`, like profile's edit buffers.
    handle_input: String,
    /// Whether `sign-out-button` has armed the inline destructive confirm — while
    /// `true` the `sign-out-confirm-button` renders (the uniform inline-confirm
    /// shape, `settings.md` § User actions). Reset when the shell re-enters.
    sign_out_pending: bool,
    /// The `settings-delete-confirm-field` type-to-confirm buffer
    /// (`settings.md` § User actions) — `settings-delete-account-button` stays
    /// disabled until this equals the literal string `"DELETE"`, mirroring
    /// web/windows. Reset when the shell re-enters (the `sign_out_pending`
    /// precedent), so a typed confirmation never survives a nav-away.
    delete_confirm_input: String,
    /// The rendered identity-export QR — `Some` only while the QR is shown
    /// (`settings.md` § Identity export). Holding the matrix (not a bool) means
    /// hiding **drops** the encoded secret rather than retaining it off-screen,
    /// matching apple/linux/web.
    identity_qr: Option<fauna_core::qr_matrix::QrMatrix>,
    /// The change-passphrase modal, armed by `credential-store-rekey-button`
    /// ([`RekeyModalState`]; `settings.md` § Credential store). Reset at the
    /// Account nav edge like [`Self::recovery`], so a half-typed passphrase
    /// never survives a nav-away.
    rekey: Option<RekeyModalState>,
    /// Whether `credential-store-rekey-success` paints — set by a successful
    /// re-key, cleared on re-arm and at the Account nav edge.
    rekey_success: bool,
    /// The Privacy sub-page's state (inbox mode / spam prefs / email filters).
    privacy: PrivacyState,
    /// The Mail sub-page's state (the shared machine + its last snapshot + the
    /// add-credential form buffer).
    mail: mail::MailState,
    /// The Devices sub-page's state (the shared `DevicesMachine` + its last
    /// snapshot — roster only, `ui/devices.md`).
    devices: devices::DevicesState,
    /// The Sessions sub-page's state — the last painted snapshot and the two
    /// confirm states (`ui/sessions.md`).
    sessions: sessions::SessionsState,
    /// The Folders sub-page's LOCAL UI state (expanded row, path-edit
    /// buffers, armed delete confirm) — the machine + snapshot are the SAME
    /// `devices.machine`/`devices.snapshot` above (`ui/folders.md`).
    folders: folders::FoldersUiState,
    /// The AT Protocol sub-page's state (the shared `AtprotoSettingsMachine` + its
    /// last snapshot + locally-revealed secrets — `ui/atproto.md`).
    atproto: atproto::AtprotoState,
    /// The Nests sub-page's state (the shared trust-enabled `LinkedNestsMachine`
    /// plus its last snapshot and the add-a-nest / mint form buffers —
    /// `ui/nests.md`).
    nests: nests::NestsState,
    /// The Muted words sub-page's state — the persisted sealed term list plus
    /// the one input buffer. **Read beyond this page:** `crate::conversations`
    /// matches a decrypted bubble's body against `words` to decide the
    /// `dm-message-muted` collapse, which is why it is loaded post-auth and not
    /// only on a visit (`muted_words.rs` module docs).
    pub(crate) muted_words: MutedWordsState,
    /// The Personalization home's **Trained topics** facet — the user's
    /// trainable tier-1 topic factors (`topic-factors.md` § Authoring surface).
    /// Sits beside `labeler_catalog` rather than inside it: they are two
    /// independent facets of one page, over two different shared seams.
    pub(crate) trained_topics: TrainedTopicsState,
    /// The Task delegation sub-page's state (the composed per-kind rows + the
    /// roster display-name map they render through — `participants.md`
    /// § Task delegation).
    pub(crate) task_delegation: TaskDelegationState,
    /// The Connected apps sub-page's state — the shared `ConnectedAppsMachine`,
    /// its last snapshot, the typed-code draft and the armed revoke.
    pub(crate) connected_apps: ConnectedAppsState,
    /// The Mail → Aliases sub-page's state — the shared `MailAliasesMachine`,
    /// its last snapshot, and the page-local add/edit + import sheet drafts
    /// (`mail-aliases.md` § Aliases UX).
    pub(crate) mail_aliases: MailAliasesState,
    /// The Mail → Lists sub-page's state — the shared `MailListsMachine`, its
    /// last snapshot, and the page-local add/edit sheet draft
    /// (`mail-mass-mailing.md` § `mail-lists` page UX).
    pub(crate) mail_lists: MailListsState,
    /// The Mail → List members sub-page's state — the **per-list**
    /// `MailListMembersMachine`, which list it is scoped to, and the
    /// page-local add + import sheet drafts.
    pub(crate) mail_list_members: MailListMembersState,
    /// The state BOTH the Personalization home and the Community-labelers catalog
    /// render from — one shared `LabelerCatalogMachine` and its last snapshot. The
    /// home is that snapshot filtered to `subscribed == true`, so the two pages can
    /// never disagree about what the user is subscribed to.
    pub(crate) labeler_catalog: LabelerCatalogState,
    /// The Personalization home's engagement-cue facet — the nest-confirmed
    /// Layer-B opt-in and the ≥k published aggregates (`engagement-cues.md`
    /// §§ Layer B / At rest). Sits beside `labeler_catalog` and
    /// `trained_topics` for the same reason they sit beside each other: three
    /// independent facets of one page, over three different shared seams.
    pub(crate) engagement: engagement_cues::EngagementCuesState,
    /// Settings → Push notifications (`settings.md` § Push notifications): the
    /// install's opt-in bit as last stored, and the last toggle's failure.
    pub(crate) push: crate::push::PushSettingsState,
    /// The Mail → Spam sub-page's state — the shared `MailSpamMachine` + its
    /// last snapshot (the classifier half) and the nest-confirmed report-share
    /// opt-in + published aggregates (the transparency half, which rides
    /// `ModerationClient`, not the machine — `report-sharing.md` § Client wire).
    pub(crate) mail_spam: MailSpamState,
    /// The Mail → Export sub-page's state — the shared `MailExportMachine`, its
    /// last snapshot, and the page-local date drafts + armed-cancel flag
    /// (`mail-export.md` § UX shape).
    pub(crate) mail_export: MailExportState,
    /// The Mail → Import sub-page's state — the shared `MailImportMachine`, its
    /// last snapshot, the page-local Source/Scope draft buffers, and the
    /// armed-cancel flag (`mailbox-migration.md` § UX shape).
    pub(crate) mail_import: mail_import::MailImportState,
    /// The Import from other services sub-page's state — the shared
    /// `ArchiveImportMachine` (or the reason the glue refused to build one),
    /// its last snapshot, the page-local path/date draft buffers, and the
    /// armed-cancel + skip-log flags (`archive-import.md` § The wizard and its
    /// machine).
    pub(crate) archive_import: archive_import::ArchiveImportState,
    /// The Web sub-page's state — the nest-confirmed `SubdomainView` and the last
    /// read/write error. No machine: the surface is one bool plus the shared pure
    /// `subdomain_view` projection, so it drives the typed `WebClient` directly
    /// (the report-share half of `mail_spam` above made the same call).
    pub(crate) web: WebSettingsState,
    /// The Subscriptions sub-page's state — the last `mine.list` read plus the
    /// claim-code buffer. No machine, the `web` reasoning: the surface is one
    /// caller-scoped list read plus two thin mutations, so it drives the typed
    /// `SubscriptionsClient`/`PaymentsClient` directly.
    pub(crate) subscriptions: SubscriptionsState,
    /// The account-switcher render snapshot (`long-term-store.md` § Multi-account
    /// evolution) — the shared `AccountRegistry`'s accounts projected for paint.
    /// Refreshed at the edges it can go stale (nav into the Account sub-page, and
    /// after a toggle/remove); a switch tears the whole surface down, so it needs
    /// no in-place refresh. Empty pre-login and off the Account sub-page.
    accounts: Vec<AccountSwitcherRow>,
    /// The Stage-2 re-auth prompt — `Some` while `account-activate-reauth-prompt`
    /// is showing for a flagged switch target. Declining (cancel/Escape) drops it
    /// with no side effect; confirming calls `set_active_confirmed` and switches
    /// (`long-term-store.md` § Per-account re-auth).
    reauth_pending: Option<ReauthPrompt>,
    /// `(actor_id, command)` copied to the clipboard by the last
    /// `account-open-new-instance-button` click, painted back as
    /// `account-open-new-instance-command` on that same row. tui cannot hand a
    /// spawned process its own tty the way a GUI toolkit hands a new process a
    /// window, so its door is manual — copy the `FAUNA_BOUND_ACCOUNT=<hex>`
    /// launch command instead of spawning (feature-catalog.md's door-neutral
    /// re-authoring, `second-identity-in-its-own-window` outcome 1,
    /// user-approved 2026-09-01). OSC 52 is fire-and-forget, so this is what
    /// the user actually got — the `admin/dns.rs`/`settings/web.rs` doctrine.
    /// Reset wherever `accounts` refreshes (`refresh_accounts`).
    open_new_instance_copied: Option<(String, String)>,
    /// `account-actor-id-copy-btn` fired since the Status landing was last
    /// entered: the button then reads "Copied!" and carries the copied actor id
    /// as its `copied` attr — linux/web's label swap, and the same contents
    /// contract the profile/web-settings copy buttons keep. Cleared on
    /// [`Action::NavBack`] and with the session.
    pub(crate) actor_id_copied: bool,
    /// The About block's newer-version check (`settings/about.rs`): idle,
    /// in flight, or its last answer. Session-local; reset with the session.
    pub(crate) update_check: about::UpdateCheck,
}

/// The pending Stage-2 re-auth confirmation for an account switch
/// (`long-term-store.md` § Per-account re-auth). Holds the target actor and its
/// display label so `account-activate-reauth-prompt` can name the account it is
/// switching to. Present only for a **flagged** target — an unflagged switch
/// never builds one.
#[derive(Debug, Clone)]
struct ReauthPrompt {
    /// The switch target's actor-id hex — passed to `set_active_confirmed` on
    /// confirm. Held (not a row index) so a snapshot refresh under the prompt
    /// can't retarget it.
    actor_id: String,
    /// The target's display label, painted into the prompt body.
    label: String,
}

/// The self-limits control's state — the self host of the shared
/// `feature-policy-editor` (`dynamic-features.md` § Authoring surfaces).
#[derive(Debug, Clone, Default)]
pub(crate) struct OwnLimitsState {
    /// The bearer's own authored documents (`fauna.features.self_limits.get`),
    /// or `None` until that read resolves — or when the read fails (any
    /// error), in which case the rows render read-only (no summary,
    /// no edit button), never a guessed "No limit set".
    pub surface: Option<fauna_client_features::AuthoredSurface>,
    /// The open editor, seeded from `surface` — `None` while closed.
    pub editor: Option<fauna_client_features::PolicyEditor>,
    /// `feature-policy-editor-status` — the last write's verdict.
    pub status: Option<String>,
}

/// A shared, fresh-read home for the account-store handle
/// ([`SettingsState::account_runtime`]).
pub(crate) type AccountRuntimeSlot =
    Arc<std::sync::Mutex<Option<fauna_sync_engine::account_runtime::AccountStoreHandle>>>;

/// The followed public folders (`fauna.state.follows`) over the
/// settings-owned account-store slot — what the follow gestures and the
/// Devices + Media pages' followed-folders source read and write through,
/// resolved at every call (`fauna_client_config::ResolvingLedgerStore`): a
/// read or write before the store lands waits for it, then answers
/// `LEDGER_NOT_READY`.
pub(crate) fn follows_door(
    runtime: AccountRuntimeSlot,
) -> Arc<dyn fauna_client_config::FollowsStore> {
    Arc::new(fauna_client_config::ResolvingLedgerStore::new(move || {
        runtime.lock().ok().and_then(|handle| handle.clone())
    }))
}

/// The period-key custody (`fauna.state.subscriptions`) over the settings-owned
/// account-store slot — what every custody surface (the author pump, the
/// feed's gated compose, the Tiers tab, the trust facet, the archive import,
/// the aftermath's rotation leg) holds from sign-in. A read before the store
/// lands meets "not running", a write waits for it
/// (`fauna_account_seams::period_keys`).
pub(crate) fn period_key_door(
    runtime: AccountRuntimeSlot,
) -> fauna_client_subscriptions::SharedPeriodKeyStore {
    Arc::new(
        fauna_client_account_runtime::period_keys::PlanePeriodKeys::new(move || {
            runtime.lock().ok().and_then(|handle| handle.clone())
        }),
    )
}

/// The folder-key custody (`fauna.state.folder-keys`) over the settings-owned
/// account-store slot — what every shared-folder custody surface (the folders
/// author, the custody-ingest sink, every key resolver, the devices and
/// folders machines, the share host, the archive import) holds from sign-in.
/// A read before the store lands meets "not running" (custody unreadable — a
/// bound set builds keyless), a write waits for it
/// (`fauna_account_seams::folder_keys`).
pub(crate) fn folder_key_door(
    runtime: AccountRuntimeSlot,
) -> Arc<dyn fauna_client_folders::FolderKeyStore> {
    Arc::new(
        fauna_client_account_runtime::folder_keys::PlaneFolderKeys::new(move || {
            runtime.lock().ok().and_then(|handle| handle.clone())
        }),
    )
}

impl SettingsState {
    /// Land (or clear) the account-store handle — both of its homes at once —
    /// returning the one it replaces. Clearing (the sign-out teardown) swaps
    /// in a FRESH slot rather than emptying the old one: the old slot belongs
    /// to the retired session, whose assembly may still land in it late, and
    /// nothing of the next session reads it.
    pub(crate) fn set_account_store(
        &mut self,
        handle: Option<fauna_sync_engine::account_runtime::AccountStoreHandle>,
    ) -> Option<fauna_sync_engine::account_runtime::AccountStoreHandle> {
        match &handle {
            Some(h) => {
                if let Ok(mut slot) = self.account_runtime.lock() {
                    *slot = Some(h.clone());
                }
            }
            None => {
                if let Ok(mut slot) = self.account_runtime.lock() {
                    *slot = None;
                }
                self.account_runtime = AccountRuntimeSlot::default();
            }
        }
        std::mem::replace(&mut self.account_store, handle)
    }

    /// The account-store handle source a shared seam reads on every use:
    /// `None` until the runtime lands and again after sign-out.
    pub(crate) fn account_runtime_source(&self) -> fauna_client_dns::AccountHandleSource {
        let slot = Arc::clone(&self.account_runtime);
        Arc::new(move || slot.lock().ok().and_then(|handle| handle.clone()))
    }

    /// [`Self::account_runtime_source`] as the preference pages hand it to the
    /// shared `preference_surfaces`: a gesture made before the runtime lands
    /// waits for it, and fails if none comes.
    pub(crate) fn preference_store(&self) -> fauna_sync_engine::account_runtime::SeatAccountStore {
        fauna_sync_engine::account_runtime::SeatAccountStore::new(self.account_runtime_source())
    }

    /// The account's mail custody (`fauna.state.mail`) over this session's
    /// runtime slot — what every mail-keyed machine tui builds reads and
    /// writes the MSEK and the credentials through, waiting for the runtime
    /// when it is not up yet.
    pub(crate) fn mail_store(&self) -> Arc<dyn fauna_client_config::MailStore> {
        Arc::new(fauna_sync_engine::account_runtime::AccountMailStore::new(
            self.account_runtime_source(),
        ))
    }
}

