    /// Leg 3's line renders on the four talking arms and falls silent on the
    /// two nothing-was-owed ones — the shared projection's decision, checked
    /// through the real render path.
    #[test]
    fn the_mls_reseal_line_renders_exactly_when_the_projection_says_to() {
        use fauna_client_mls_sync::{ReplicaResealOutcome, ReplicaResealProgress};
        let mut app = crate::app::tests::authed_app();
        app.settings.sub = SubPage::Account;

        for rendering in [
            ReplicaResealProgress::Running,
            ReplicaResealProgress::Settled(ReplicaResealOutcome::Resealed {
                provider: true,
                histories: 1,
                owed: 0,
            }),
            ReplicaResealProgress::Settled(ReplicaResealOutcome::Resealed {
                provider: true,
                histories: 1,
                owed: 2,
            }),
            ReplicaResealProgress::Settled(ReplicaResealOutcome::NoKeyOpensIt),
            ReplicaResealProgress::Failed("nest unreachable".into()),
        ] {
            app.aftermath.mls_reseal = Some(rendering.clone());
            let els = elements(&app);
            assert!(
                els.iter().any(|e| e.id == "recovery-kit-mls-reseal-status"),
                "{rendering:?} must render a progress line"
            );
        }

        for silent in [
            ReplicaResealProgress::Settled(ReplicaResealOutcome::AlreadyCurrent),
            ReplicaResealProgress::Settled(ReplicaResealOutcome::NothingStored),
        ] {
            app.aftermath.mls_reseal = Some(silent.clone());
            let ids: Vec<String> = elements(&app).iter().map(|e| e.id.clone()).collect();
            assert!(
                !ids.contains(&"recovery-kit-mls-reseal-status".to_string()),
                "{silent:?} owes nothing — it must render no line"
            );
        }
    }

    /// The state leg 3 has and the other two legs do not: a pass that unlocked
    /// some conversations and left others sealed to an identity this device
    /// cannot open. It is progress AND unfinished, so it must render its own
    /// line — never the done one, which would tell the user every conversation
    /// is back while some are still dark. Asserted on the rendered TEXT,
    /// because a key-level check would sail past exactly that drift.
    #[test]
    fn a_partly_owed_mls_pass_never_renders_as_done() {
        use fauna_client_mls_sync::{ReplicaResealOutcome, ReplicaResealProgress};
        let mut app = crate::app::tests::authed_app();
        app.settings.sub = SubPage::Account;

        app.aftermath.mls_reseal = Some(ReplicaResealProgress::Settled(
            ReplicaResealOutcome::Resealed {
                provider: true,
                histories: 3,
                owed: 0,
            },
        ));
        let done = el(&elements(&app), "recovery-kit-mls-reseal-status")
            .expect("the done arm renders")
            .text
            .clone();

        app.aftermath.mls_reseal = Some(ReplicaResealProgress::Settled(
            ReplicaResealOutcome::Resealed {
                provider: true,
                histories: 3,
                owed: 1,
            },
        ));
        let partly = el(&elements(&app), "recovery-kit-mls-reseal-status")
            .expect("the partly-owed arm renders")
            .text
            .clone();

        assert_ne!(
            partly, done,
            "a partly-owed pass must not reuse the done copy"
        );
        let lowered = partly.to_lowercase();
        assert!(
            lowered.contains("some"),
            "the partly-owed line must say only SOME conversations are still held: {partly:?}"
        );
        // The still-owed rule: intact data, never damage.
        for alarming in ["corrupt", "damaged", "destroyed"] {
            assert!(
                !lowered.contains(alarming),
                "the partly-owed line must not describe intact data as {alarming}: {partly:?}"
            );
        }
    }

