    /// The copy button carries the URI, not the bare hex on screen (ruling
    /// 2026-08-02). The point is what a *restore* can do with what was copied:
    /// a device that has never seen this account learns which account it is and
    /// where it lives, so the user types nothing. Copying is what a terminal
    /// user does — the QR beside it already carried this, and the mismatch
    /// between the two encodings was the bug.
    #[test]
    fn the_copy_button_carries_the_uri_so_a_restore_needs_nothing_typed() {
        let secret = "ab".repeat(32);
        let actor = "cd".repeat(32);
        let uri = fauna_core::recovery::RecoveryKitQr::to_uri(
            &secret,
            Some(&actor),
            Some("ada@nest.example"),
        );
        let minted = recovery::MintedKit {
            secret_hex: secret.clone().into(),
            uri: uri.clone().into(),
            ..Default::default()
        };

        assert_eq!(
            minted.copy_payload(),
            uri,
            "the clipboard gets the URI; the bare hex is what the DISPLAY shows"
        );

        // The property that makes it worth doing: the copied payload restores
        // through the one shared grammar, carrying both locators.
        let parsed = fauna_client_recovery::parse_kit(minted.copy_payload())
            .expect("the copied payload is a kit the shared grammar accepts");
        assert_eq!(
            parsed.handle.as_deref(),
            Some("ada@nest.example"),
            "only the handle's @domain can find the home nest, and the restore \
             is pre-identity — it has no session to ask"
        );
        assert_eq!(
            parsed.actor_id.map(|a| a.to_hex()).as_deref(),
            Some(actor.as_str()),
        );
    }

