    #[test]
    fn inbox_mode_buttons_reflect_the_current_selection() {
        let mut app = crate::app::tests::authed_app();
        app.settings.sub = SubPage::Privacy;
        app.settings.privacy.inbox_mode = Some("contacts_only".to_string());
        let els = elements(&app);
        for (mode, selected) in [
            ("inbox-mode-open", false),
            ("inbox-mode-allow_knock", false),
            ("inbox-mode-contacts_only", true),
            ("inbox-mode-closed", false),
        ] {
            let el = els.iter().find(|e| e.id == mode).unwrap();
            match &el.role {
                // One-of-N group → Radio (the control-vocabulary rule,
                // tui.md § Rendering), with the toggle convention's `state`
                // attr mirroring the paint for drivers.
                crate::element::Role::Radio { selected: s, .. } => {
                    assert_eq!(*s, selected, "{mode} selected state");
                }
                other => panic!("{mode} should be a radio option, got {other:?}"),
            }
            let state = el
                .attrs
                .iter()
                .find(|(k, _)| k == "state")
                .map(|(_, v)| v.as_str());
            assert_eq!(
                state,
                Some(if selected { "on" } else { "off" }),
                "{mode} state attr mirrors the selection"
            );
        }
    }

