    /// The member card's two-step remove: arm and cancel are view state on
    /// the card's index, and only the confirm issues the op — disarming as it
    /// does, so a refusal leaves the card to re-arm rather than a stale pair.
    #[test]
    fn remove_member_arms_a_confirm_and_only_the_confirm_issues_the_op() {
        let mut app = crate::app::tests::authed_app();
        app.settings.devices = devices::DevicesState::build(
            nest_for_test(),
            "",
            &[],
            follows_door(Default::default()),
        );
        let id = || "22".repeat(32);
        apply(&mut app.settings, Action::RemoveMember(id()));
        assert_eq!(app.settings.devices.member_remove_pending, Some(id()));
        apply(&mut app.settings, Action::CancelRemoveMember);
        assert_eq!(app.settings.devices.member_remove_pending, None);
        apply(&mut app.settings, Action::RemoveMember(id()));
        let op = apply_local(&mut app, Action::ConfirmRemoveMember(id()));
        assert!(
            matches!(&op, Some(Op::RemoveMember { device_id, .. }) if *device_id == id()),
            "ConfirmRemoveMember must forward its card's key into the op"
        );
        assert_eq!(
            app.settings.devices.member_remove_pending, None,
            "the confirm disarms"
        );
        // A fresh visit disarms too.
        apply(&mut app.settings, Action::RemoveMember(id()));
        route_subpage(&mut app.settings, Some("devices"), None);
        assert_eq!(app.settings.devices.member_remove_pending, None);
    }

