    // ── The inherited-filter review plane (succession-aftermath.md § Adjudicating
    //    what the aftermath carries across, the fourth plane, 2026-08-14) ──

    /// **The remedy that was found missing.** A rule the succession carried
    /// across is marked *on the row*, with a Keep beside it — and an ordinary
    /// rule beside it carries neither, or the mark would say nothing.
    #[test]
    fn only_an_inherited_filter_row_paints_the_mark_and_its_keep() {
        let mut app = crate::app::tests::authed_app();
        app.settings.sub = SubPage::Privacy;
        app.settings.privacy.filters = vec![
            sample_filter(11, "Bin everything", EmailFilterAction::Discard),
            sample_filter(22, "My own rule", EmailFilterAction::Allow),
        ];
        app.filter_marks = vec![11];

        let els = elements(&app);
        let marks: Vec<&Element> = els
            .iter()
            .filter(|e| e.id == "filter-unattested-mark")
            .collect();
        assert_eq!(
            marks.len(),
            1,
            "exactly the raised row is marked — a mark on every row says nothing"
        );
        assert_eq!(
            marks[0].path,
            vec![("filter-item".to_string(), 0)],
            "the mark is scoped to ITS row, or the successor cannot tell which rule it means"
        );

        let keeps: Vec<&Element> = els
            .iter()
            .filter(|e| e.id == "filter-review-keep-button")
            .collect();
        assert_eq!(keeps.len(), 1);
        assert_eq!(keeps[0].path, vec![("filter-item".to_string(), 0)]);
        match &keeps[0].role {
            crate::element::Role::Button(Gesture::Settings(Action::KeepFilter(id))) => {
                assert_eq!(*id, 11, "the Keep must name the row it was painted beside")
            }
            other => panic!("expected a KeepFilter gesture, got {other:?}"),
        }
    }

    /// **There is no Remove twin, and that is the ruling.** `filter-delete` is
    /// the Remove half (the no-second-removal-mechanism rule), so it must still
    /// render on a marked row — a review that hid the ordinary delete would
    /// leave the successor able to flag a thief's rule but not to get rid of it.
    #[test]
    fn a_marked_row_keeps_its_ordinary_delete_as_the_remove_half() {
        let mut app = crate::app::tests::authed_app();
        app.settings.sub = SubPage::Privacy;
        app.settings.privacy.filters = vec![sample_filter(
            11,
            "Bin everything",
            EmailFilterAction::Discard,
        )];
        app.filter_marks = vec![11];

        let els = elements(&app);
        assert_eq!(
            els.iter().filter(|e| e.id == "filter-delete").count(),
            1,
            "the delete affordance IS the Remove half; it may never be hidden by the review"
        );
        assert!(
            !els.iter().any(|e| e.id == "filter-review-remove-button"),
            "a second removal control would be a second way to delete a rule"
        );
    }

    /// Nothing paints for an account that never ran a recovery — the ordinary
    /// state of every session, and what keeps this from becoming clutter.
    #[test]
    fn an_unraised_filter_list_paints_no_review_affordances() {
        let mut app = crate::app::tests::authed_app();
        app.settings.sub = SubPage::Privacy;
        app.settings.privacy.filters =
            vec![sample_filter(11, "My own rule", EmailFilterAction::Allow)];

        let els = elements(&app);
        assert!(
            !els.iter()
                .any(|e| e.id == "filter-unattested-mark" || e.id == "filter-review-keep-button")
        );
    }

    /// Delete on a **marked** row carries the config seam, so the verdict is
    /// recorded with the removal; delete on an ordinary row does not, so a
    /// routine delete stays one round trip.
    #[test]
    fn delete_carries_the_marks_store_only_for_a_raised_row() {
        let mut app = crate::app::tests::authed_app();
        app.settings.nest = Some(nest_for_test());
        // The marks live on the succession ledger's plane since its cut, so
        // the seam a marked delete carries is the ledger store.
        let (_manager, store, _other) = removal_fixture(false);
        app.ledger_store = Some(store);
        app.filter_marks = vec![11];

        match apply_local(&mut app, Action::DeleteFilter(11)) {
            Some(Op::DeleteFilter { marks_store, .. }) => assert!(
                marks_store.is_some(),
                "a marked row's delete IS the Remove verdict — without the seam the mark \
                 outlives the rule and the review line never reaches zero"
            ),
            _ => panic!("expected a DeleteFilter op"),
        }
        match apply_local(&mut app, Action::DeleteFilter(22)) {
            Some(Op::DeleteFilter { marks_store, .. }) => assert!(
                marks_store.is_none(),
                "an ordinary delete must not pay for a ledger read"
            ),
            _ => panic!("expected a DeleteFilter op"),
        }
    }

    /// The aftermath line renders **only** while rules are unadjudicated, and
    /// disappears by itself — the honest done state of a backlog is no line.
    #[test]
    fn the_aftermath_routes_to_the_filter_list_only_while_rules_are_open() {
        let mut app = crate::app::tests::authed_app();
        app.settings.sub = SubPage::Account;

        assert!(
            !elements(&app)
                .iter()
                .any(|e| e.id == "recovery-kit-inherited-filters-status"),
            "an account that never ran a recovery carries no line"
        );

        app.filter_marks = vec![11, 22];
        let line = elements(&app)
            .into_iter()
            .find(|e| e.id == "recovery-kit-inherited-filters-status")
            .expect("open rules must route the successor somewhere");
        assert!(
            line.text.contains('2'),
            "the line names how many rules are waiting; got {:?}",
            line.text
        );

        app.filter_marks.clear();
        assert!(
            !elements(&app)
                .iter()
                .any(|e| e.id == "recovery-kit-inherited-filters-status"),
            "a worked-through backlog leaves no standing clutter"
        );
    }

    #[test]
    fn filter_edit_renders_scoped_and_gated_on_editability() {
        let mut app = crate::app::tests::authed_app();
        app.settings.sub = SubPage::Privacy;
        let mut multi_rule = sample_filter(33, "Raw API filter", EmailFilterAction::Allow);
        multi_rule.rules.push(EmailFilterRule::SubjectContains {
            text: "urgent".into(),
        });
        app.settings.privacy.filters = vec![
            sample_filter(11, "Block spam", EmailFilterAction::Discard),
            multi_rule,
        ];
        let els = elements(&app);
        // Row 0 (single-rule, encodable) gets the edit affordance, scoped under
        // its own `filter-item[0]` occurrence — the one exception to this row's
        // otherwise-flat convention.
        let edit_row0: Vec<&Element> = els
            .iter()
            .filter(|e| e.id == "filter-edit" && e.path == vec![("filter-item".to_string(), 0)])
            .collect();
        assert_eq!(
            edit_row0.len(),
            1,
            "row 0 must offer exactly one filter-edit"
        );
        match &edit_row0[0].role {
            crate::element::Role::Button(Gesture::Settings(Action::OpenEditFilterForm(id))) => {
                assert_eq!(*id, 11);
            }
            other => panic!("expected OpenEditFilterForm gesture, got {other:?}"),
        }
        // Row 1 (multi-rule — only a raw API call could have produced it) never
        // opens a form that would silently narrow it on save.
        assert_eq!(
            els.iter()
                .filter(|e| e.id == "filter-edit" && e.path == vec![("filter-item".to_string(), 1)])
                .count(),
            0,
            "a filter outside the dropdown-covered subset must not offer edit"
        );
        assert_eq!(
            els.iter().filter(|e| e.id == "filter-edit").count(),
            1,
            "exactly one row is editable"
        );
    }

